-- ════════════════════════════════════════════════════════════════════
-- VoltageAfrica CMS · 006 · Cinematic homepage
-- Turns the homepage into a seven-act story with a film / 3D hero.
--
-- Non-destructive and safe to re-run:
--   • new sections and media use fixed IDs and "on conflict do nothing"
--   • hero settings are only ADDED where missing; the hero buttons are only
--     changed if they still carry their original (seeded) wording
--   • superseded homepage sections are HIDDEN, not deleted. Switch them back
--     on in Admin → Homepage if you want them.
-- ════════════════════════════════════════════════════════════════════
begin;

-- Illustrative renders for the hero film and the closing act
insert into public.media_assets (id, bucket, path, file_name, title, alt_text, caption, mime_type, category) values
  ('9339d119-34cb-5a2c-adb5-f7fbe2111d71', 'static', '/images/renders/hub-golden.jpg', 'hub-golden.jpg', 'Illustrative render: community hub at golden hour', 'Illustrative 3D render: rows of solar trackers beside a small battery container, with savanna woodland and a low golden sun behind', 'Illustrative render of a proposed community energy hub at golden hour. Not an existing installation.', 'image/jpeg', 'renders'),
  ('13a82779-6173-559c-9c15-bbad4f9e1462', 'static', '/images/renders/hub-dusk.jpg', 'hub-dusk.jpg', 'Illustrative render: connected community at dusk', 'Illustrative 3D render: a rural community at dusk with lit windows and power lines under an orange afterglow', 'Illustrative render of a connected community at dusk. A vision, not an existing installation.', 'image/jpeg', 'renders')
on conflict (id) do nothing;

-- Hero: add the film scenes and experience settings where they are missing
update public.page_sections set content = '{"scenes":[{"image":{"id":"b39ec6d7-77ee-5855-ac7f-ad216a284d84","src":"/images/landscape/matobo-view.jpg","alt":"Sunlight breaking through a rain storm over the granite kopjes and woodland of the Matobo Hills, Zimbabwe"},"title":"The land","caption":"Light through a storm over the Matobo Hills, Zimbabwe.","position":"50% 55%","motion":"in"},{"image":{"id":"832709ee-0938-5546-a656-1d4d78197041","src":"/images/outreach/kigali-courtyard.jpg","alt":"Students and teachers gathered outside a brick school building in Kigali after a VoltageAfrica lesson"},"title":"The people","caption":"Students and teachers after a VoltageAfrica climate education session in Kigali, Rwanda.","position":"50% 62%","motion":"right"},{"image":{"id":"fcba3f86-e401-563f-bced-08d57df88df7","src":"/images/commons/mini-grid-bayelsa.jpg","alt":"Aerial view of a fenced solar mini-grid with rows of panels and a small power house, beside forest, a river and a town in Bayelsa, Nigeria"},"title":"The energy","caption":"A solar mini-grid serving a community in Bayelsa, Nigeria. Not a VoltageAfrica installation.","position":"66% 66%","motion":"left"},{"image":{"id":"02540fe5-f430-5c65-b686-24dce1be83a6","src":"/images/commons/battery-storage-schwerin.jpg","alt":"Long aisles of battery racks and control cabinets inside the WEMAG battery storage hall in Schwerin, Germany"},"title":"The intelligence","caption":"Battery racks under continuous computer control at the WEMAG storage plant, Schwerin, Germany. Not a VoltageAfrica installation.","position":"50% 50%","motion":"in"},{"image":{"id":"65fa27c4-697d-5cc2-90ea-930dfb71eeaf","src":"/images/commons/golden-sunset-kampala.jpg","alt":"The sun setting behind the silhouette of a great spreading tree, with warm golden light, in Kawempe, Kampala, Uganda"},"title":"The future","caption":"Golden sunset in Kawempe, Kampala, Uganda.","position":"56% 52%","motion":"out"}],"sceneDuration":8,"enable3d":true,"defaultMode":"film"}'::jsonb || content
  where id = '23fbf37c-1176-59e3-b0a8-a8de2cd7614f' and not (content ? 'scenes');
update public.page_section_drafts set content = '{"scenes":[{"image":{"id":"b39ec6d7-77ee-5855-ac7f-ad216a284d84","src":"/images/landscape/matobo-view.jpg","alt":"Sunlight breaking through a rain storm over the granite kopjes and woodland of the Matobo Hills, Zimbabwe"},"title":"The land","caption":"Light through a storm over the Matobo Hills, Zimbabwe.","position":"50% 55%","motion":"in"},{"image":{"id":"832709ee-0938-5546-a656-1d4d78197041","src":"/images/outreach/kigali-courtyard.jpg","alt":"Students and teachers gathered outside a brick school building in Kigali after a VoltageAfrica lesson"},"title":"The people","caption":"Students and teachers after a VoltageAfrica climate education session in Kigali, Rwanda.","position":"50% 62%","motion":"right"},{"image":{"id":"fcba3f86-e401-563f-bced-08d57df88df7","src":"/images/commons/mini-grid-bayelsa.jpg","alt":"Aerial view of a fenced solar mini-grid with rows of panels and a small power house, beside forest, a river and a town in Bayelsa, Nigeria"},"title":"The energy","caption":"A solar mini-grid serving a community in Bayelsa, Nigeria. Not a VoltageAfrica installation.","position":"66% 66%","motion":"left"},{"image":{"id":"02540fe5-f430-5c65-b686-24dce1be83a6","src":"/images/commons/battery-storage-schwerin.jpg","alt":"Long aisles of battery racks and control cabinets inside the WEMAG battery storage hall in Schwerin, Germany"},"title":"The intelligence","caption":"Battery racks under continuous computer control at the WEMAG storage plant, Schwerin, Germany. Not a VoltageAfrica installation.","position":"50% 50%","motion":"in"},{"image":{"id":"65fa27c4-697d-5cc2-90ea-930dfb71eeaf","src":"/images/commons/golden-sunset-kampala.jpg","alt":"The sun setting behind the silhouette of a great spreading tree, with warm golden light, in Kawempe, Kampala, Uganda"},"title":"The future","caption":"Golden sunset in Kawempe, Kampala, Uganda.","position":"56% 52%","motion":"out"}],"sceneDuration":8,"enable3d":true,"defaultMode":"film"}'::jsonb || content
  where section_id = '23fbf37c-1176-59e3-b0a8-a8de2cd7614f' and not (content ? 'scenes');
update public.page_sections set content = jsonb_set(content, '{primaryCta}', '{"label":"Explore our vision","href":"/vision"}'::jsonb)
  where id = '23fbf37c-1176-59e3-b0a8-a8de2cd7614f' and content -> 'primaryCta' = '{"label":"Explore the microgrid","href":"#microgrid"}'::jsonb;
update public.page_sections set content = jsonb_set(content, '{secondaryCta}', '{"label":"Partner with us","href":"/partner"}'::jsonb)
  where id = '23fbf37c-1176-59e3-b0a8-a8de2cd7614f' and content -> 'secondaryCta' = '{"label":"Read our vision","href":"/vision"}'::jsonb;

-- Act III reuses the 3D exhibit
update public.page_sections set content = jsonb_set(content, '{kicker}', '"Act III · The system"'::jsonb)
  where id = 'ce116db1-a19b-56c0-b8a5-27ab3641d123' and content ->> 'kicker' = 'The exhibit';

-- The new acts (only when the homepage exists)
insert into public.page_sections (id, page_id, type, label, content, settings, status, is_visible, sort_order)
select v.id::uuid, '9e36afb6-9da0-5bf9-91f6-c860dbce5e93'::uuid, v.type, v.label, v.content::jsonb, v.settings::jsonb, 'published', true, v.sort_order
from (values
  ('8358febe-6790-5f4a-addf-51b194b55179', 'act', 'Act I · The reality', '{"layout":"reality","numeral":"I","kicker":"The reality","headline":"When night falls across rural Africa, *opportunity switches off.*","body":"Without reliable electricity, children study by candlelight, clinics cannot keep vaccines cold, and small businesses close at dusk. Scarce household income goes on kerosene, candles, firewood and paying someone else to charge a phone.","image":{"id":"bb75451a-ffc4-5e7a-9d96-c828dc31260c","src":"/images/landscape/chidoma-dusk.jpg","alt":"Chidoma Kopje and the Mapfungautsi Plateau rendered in deep dusk tones"},"imageCaption":"Chidoma Kopje beside the Mapfungautsi Plateau, Midlands Province, Zimbabwe (tonally treated).","imagePosition":"50% 60%","stats":[{"value":"600","unit":"million","label":"people in Africa lived without electricity in 2021: 43% of the continent''s population.","source":"IEA, Africa Energy Outlook 2022","sourceUrl":"https://www.iea.org/reports/africa-energy-outlook-2022/key-findings"},{"value":"23.4","unit":"%","label":"of rural residents in Zimbabwe have access to grid electricity, against 87.4% in urban areas.","source":"ZimStat 2022 Population & Housing Census, as reported by DevelopmentAid","sourceUrl":"https://www.developmentaid.org/news-stream/post/189995/electricity-access-in-rural-zimbabwe"},{"value":"970","unit":"million","label":"Africans lack access to clean cooking, relying on wood, charcoal and kerosene.","source":"IEA, Africa Energy Outlook 2022","sourceUrl":"https://www.iea.org/reports/africa-energy-outlook-2022/key-findings"}]}', '{"anchor":"reality"}', 1),
  ('882c789b-fd9f-525f-a454-da2d03480762', 'act', 'Act II · The idea', '{"layout":"split","numeral":"II","kicker":"The idea","headline":"Start with one community. *Build the system it actually needs.*","body":"VoltageAfrica designs complete local energy systems (generation, storage, intelligence and distribution) around the homes, schools and enterprises they serve. We began by listening, then by building.","image":{"id":"e24fa183-d39e-5832-a4ec-963c2187bdc4","src":"/images/prototype/tracker-array.jpg","alt":"VoltageAfrica''s prototype: four solar modules arranged around a central light-sensor module"},"imageCaption":"VoltageAfrica’s sun-tracking prototype, 2025: four 15 W modules steered by a central light sensor.","imagePosition":"50% 50%","images":[{"image":{"id":"9312dba9-831c-5676-a6ce-340875d38954","src":"/images/founder/sean-field.jpg","alt":"Sean Mavhima planting a tree in dense green bush"},"caption":"Sean Mavhima, founder, in the field."}],"points":[{"title":"Listen first","body":"23 household interviews, 6 community leaders and 27 surveys across five Shurugwi villages in May 2025."},{"title":"Prototype and measure","body":"A sun-tracking rig of four 15 W modules, built and tested in 2025."},{"title":"Design for productive use","body":"Hubs sized around mills, pumps and cold rooms as well as homes, because income is what makes energy access last."}],"cta":{"label":"Our approach","href":"/technology#approach"}}', '{"anchor":"idea"}', 2),
  ('5faaba5f-c820-5ea3-bd35-c0fff74e9e77', 'act', 'Act IV · The intelligence', '{"layout":"register","numeral":"IV","kicker":"The intelligence","headline":"An intelligence layer, *stated honestly.*","body":"Monitoring, metering and control come first. Forecasting and optimisation follow once a live hub produces real operating data. Here is exactly where each capability stands today.","cta":{"label":"How the technology works","href":"/technology#intelligence"},"note":"We do not yet operate AI systems in any community. Statuses are updated as work progresses."}', '{"anchor":"intelligence"}', 4),
  ('437b3c3f-ecde-5751-a794-f135697ff932', 'act', 'Act V · The impact', '{"layout":"mosaic","numeral":"V","kicker":"The impact","headline":"Electricity is not the end goal. *It is the foundation.*","body":"Light for evening study. Cold storage for medicines and harvests. Power for the mill, the pump and the workshop. Energy matters for what it lets people do.","images":[{"image":{"id":"fe4ed70e-7393-5701-a6bb-6e6537ff5e24","src":"/images/outreach/kigali-classroom.jpg","alt":"A class gathered after a conservation and renewable energy lesson"},"caption":"A class after a VoltageAfrica conservation and renewable energy lesson, Kigali."},{"image":{"id":"3bda21c7-d6c8-5587-8107-99ab13439e22","src":"/images/milestones/green-generation-planting.jpg","alt":"Sean Mavhima and fellow participants tree planting with the Green Generation Initiative"},"caption":"Tree planting with the Green Generation Initiative."},{"image":{"id":"df03f173-41d0-595e-aae9-358cc22e559d","src":"/images/outreach/kigali-school-group.jpg","alt":"Students and the VoltageAfrica team outside a classroom after a renewable energy lesson in Kigali"},"caption":"Students and the team after a lesson in Kigali."}],"points":[{"title":"Evening study","body":"Light that lets learning continue after sunset, without candles or kerosene smoke."},{"title":"Health","body":"Refrigeration for vaccines and medicines, and power for basic clinical equipment."},{"title":"Water","body":"Pumping and irrigation that turn a single rainy season into year-round growing."},{"title":"Enterprise","body":"Milling, welding, tailoring, cold storage: the machines that make local income possible."},{"title":"Connection","body":"Phone charging and mobile money: access to markets, information and family."},{"title":"Forests","body":"Less pressure on woodland where firewood is the only fuel a household can reach."}],"note":"What reliable energy makes possible, as described in our community research. VoltageAfrica will publish measured impact once its first hub is operating."}', '{"anchor":"impact"}', 5),
  ('0453b8b1-0853-5e1f-887a-63e37491d47d', 'future', null, '{"kicker":"Act VI · The ambition","headline":"One village today. *A network tomorrow.*","intro":"Every hub we build is designed to connect with the next. Over time, many small, intelligent microgrids can work together as a distributed energy network and, eventually, as a virtual power plant.","stages":[{"title":"Community microgrids","horizon":"Now: preparing the first pilot","body":"Solar, storage and distribution serving a single community. The Shurugwi pilot hub is our first."},{"title":"Intelligent energy management","horizon":"Next","body":"Monitoring, metering and forecasting that let each hub run more efficiently and affordably."},{"title":"Connected energy assets","horizon":"Next phase","body":"Batteries, inverters, meters and productive equipment reporting into one platform."},{"title":"Distributed energy network","horizon":"Later","body":"Neighbouring microgrids able to share energy, so surplus in one community supports another."},{"title":"Virtual power plant","horizon":"Long-term vision","body":"Many distributed assets coordinated as one flexible resource that supports the wider grid. This is where we are heading. We do not operate one today."}]}', '{"anchor":"ambition"}', 6),
  ('b9bdd9d2-bb71-5060-8a7c-c5b22bd6e5db', 'act', 'Act VII · Invitation', '{"layout":"invitation","numeral":"VII","kicker":"Invitation","headline":"Let’s build what *comes next.*","body":"We are preparing our first pilot and looking for people and organisations who want to help build intelligent energy infrastructure for rural Africa.","image":{"id":"13a82779-6173-559c-9c15-bbad4f9e1462","src":"/images/renders/hub-dusk.jpg","alt":"Illustrative 3D render: a rural community at dusk with lit windows and power lines under an orange afterglow"},"imageCaption":"Illustrative render of a connected community at dusk. A vision, not an existing installation.","imagePosition":"50% 50%","links":[{"title":"Partner with us","body":"Collaborate on engineering, equipment, research, funding or community implementation.","href":"/partner"},{"title":"Support our work","body":"Offer funding, equipment, technical expertise or institutional support.","href":"/support"},{"title":"Contact us","body":"Media, speaking invitations, volunteering, careers or a general question.","href":"/contact"}]}', '{"anchor":"get-involved"}', 7)
) as v(id, type, label, content, settings, sort_order)
where exists (select 1 from public.pages where id = '9e36afb6-9da0-5bf9-91f6-c860dbce5e93')
on conflict (id) do nothing;

-- Story order (first run only: while the superseded sections are still visible,
-- so a later re-run never undoes reordering done in the page builder)
update public.page_sections set sort_order = 0 where id = '23fbf37c-1176-59e3-b0a8-a8de2cd7614f' and exists (select 1 from public.page_sections r where r.id in ('dfe7f61b-e210-5a34-8ccc-278f6dc0cf45', '01c23043-50d1-5007-b05b-5a0a7027446b', 'f55a9f38-8a6f-50a9-a933-eca2e52e6409', '61aa613d-f6b9-57a6-9f42-aa2e7e1dfe22') and r.is_visible and r.sort_order < 100);
update public.page_sections set sort_order = 1 where id = '8358febe-6790-5f4a-addf-51b194b55179' and exists (select 1 from public.page_sections r where r.id in ('dfe7f61b-e210-5a34-8ccc-278f6dc0cf45', '01c23043-50d1-5007-b05b-5a0a7027446b', 'f55a9f38-8a6f-50a9-a933-eca2e52e6409', '61aa613d-f6b9-57a6-9f42-aa2e7e1dfe22') and r.is_visible and r.sort_order < 100);
update public.page_sections set sort_order = 2 where id = '882c789b-fd9f-525f-a454-da2d03480762' and exists (select 1 from public.page_sections r where r.id in ('dfe7f61b-e210-5a34-8ccc-278f6dc0cf45', '01c23043-50d1-5007-b05b-5a0a7027446b', 'f55a9f38-8a6f-50a9-a933-eca2e52e6409', '61aa613d-f6b9-57a6-9f42-aa2e7e1dfe22') and r.is_visible and r.sort_order < 100);
update public.page_sections set sort_order = 3 where id = 'ce116db1-a19b-56c0-b8a5-27ab3641d123' and exists (select 1 from public.page_sections r where r.id in ('dfe7f61b-e210-5a34-8ccc-278f6dc0cf45', '01c23043-50d1-5007-b05b-5a0a7027446b', 'f55a9f38-8a6f-50a9-a933-eca2e52e6409', '61aa613d-f6b9-57a6-9f42-aa2e7e1dfe22') and r.is_visible and r.sort_order < 100);
update public.page_sections set sort_order = 4 where id = '5faaba5f-c820-5ea3-bd35-c0fff74e9e77' and exists (select 1 from public.page_sections r where r.id in ('dfe7f61b-e210-5a34-8ccc-278f6dc0cf45', '01c23043-50d1-5007-b05b-5a0a7027446b', 'f55a9f38-8a6f-50a9-a933-eca2e52e6409', '61aa613d-f6b9-57a6-9f42-aa2e7e1dfe22') and r.is_visible and r.sort_order < 100);
update public.page_sections set sort_order = 5 where id = '437b3c3f-ecde-5751-a794-f135697ff932' and exists (select 1 from public.page_sections r where r.id in ('dfe7f61b-e210-5a34-8ccc-278f6dc0cf45', '01c23043-50d1-5007-b05b-5a0a7027446b', 'f55a9f38-8a6f-50a9-a933-eca2e52e6409', '61aa613d-f6b9-57a6-9f42-aa2e7e1dfe22') and r.is_visible and r.sort_order < 100);
update public.page_sections set sort_order = 6 where id = '0453b8b1-0853-5e1f-887a-63e37491d47d' and exists (select 1 from public.page_sections r where r.id in ('dfe7f61b-e210-5a34-8ccc-278f6dc0cf45', '01c23043-50d1-5007-b05b-5a0a7027446b', 'f55a9f38-8a6f-50a9-a933-eca2e52e6409', '61aa613d-f6b9-57a6-9f42-aa2e7e1dfe22') and r.is_visible and r.sort_order < 100);
update public.page_sections set sort_order = 7 where id = 'b9bdd9d2-bb71-5060-8a7c-c5b22bd6e5db' and exists (select 1 from public.page_sections r where r.id in ('dfe7f61b-e210-5a34-8ccc-278f6dc0cf45', '01c23043-50d1-5007-b05b-5a0a7027446b', 'f55a9f38-8a6f-50a9-a933-eca2e52e6409', '61aa613d-f6b9-57a6-9f42-aa2e7e1dfe22') and r.is_visible and r.sort_order < 100);

-- Superseded by Act VII (hidden, not deleted)
update public.page_sections set is_visible = false, sort_order = sort_order + 100
